<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($manual['title'])?></title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1000px;margin:auto;padding:1rem}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;background:#eef2f5;padding:1rem;border-radius:8px}.section{border-top:1px solid #ccd3da;padding-top:1rem;white-space:pre-wrap}.actions{display:flex;gap:1rem;flex-wrap:wrap}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}.pass{color:#176b32}.fail{color:#a51d2d}@media(max-width:700px){.meta,.checks{grid-template-columns:1fr}}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main><p><a href="/program-manuals">← Program manuals</a></p><h1><?=$h($manual['title'])?></h1><div class="meta"><div><strong>Program</strong><br><?=$h($manual['program_name'].' '.$manual['program_code'])?></div><div><strong>Version</strong><br><?=$h($manual['version_label'])?> (<?=$h($manual['academic_period'])?>)</div><div><strong>Status</strong><br><?=$h($manual['status'])?></div><div><strong>Prepared by</strong><br><?=$h($manual['prepared_by'])?></div><div><strong>Approved by</strong><br><?=$h($manual['approved_by'])?></div><div><strong>Next review</strong><br><?=$h($manual['next_review_date'])?></div></div><h2>Readiness: <?=(int)$readiness['score']?>%</h2><div class="checks"><?php foreach($readiness['checks']as$name=>$pass):?><div class="<?=$pass?'pass':'fail'?>"><?=$pass?'✓':'✗'?> <?=$h(ucwords(str_replace('_',' ',$name)))?></div><?php endforeach;?></div><p><strong>Coordination:</strong> <?=(int)$coordination['staff_count']?> matching staff records and <?=(int)$coordination['committee_count']?> active committees are available for review.</p><p class="actions"><a class="btn" href="/program-manuals/<?=(int)$manual['id']?>/download">Download verified PDF</a><a href="/program-manuals/<?=(int)$manual['id']?>/compare">Compare summary</a><a href="/program-manuals/<?=(int)$manual['id']?>/details">Compare PLOs and curriculum</a><a href="/program-manuals/<?=(int)$manual['id']?>/archive">Evidence archive</a><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')):?><a href="/program-manuals/<?=(int)$manual['id']?>/edit">Edit</a><?php endif;?></p><h2>Reconciliation approval: <?=$h($manual['reconciliation_status'])?></h2><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')&&$manual['reconciliation_status']!=='Approved'):?><form method="post" action="/program-manuals/<?=(int)$manual['id']?>/workflow"><?=csrfField()?><input type="hidden" name="action" value="submit"><label>Submission note <input name="note"></label><button>Submit for approval</button></form><?php endif;?><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','approve')&&$manual['reconciliation_status']==='Pending Approval'):?><form method="post" action="/program-manuals/<?=(int)$manual['id']?>/workflow"><?=csrfField()?><label>Approval note <input name="note"></label><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?><h2>Revision history</h2><ul><?php foreach($revisions as$r):?><li><a href="/program-manuals/<?=(int)$r['id']?>"><?=$h($r['version_label'])?></a> - <?=$h($r['status'])?></li><?php endforeach;?></ul><?php foreach($sections as$s):?><section class="section"><h2><?=$h($s['heading'])?></h2><?=$h($s['content'])?></section><?php endforeach;?></main></body></html>
